<?php
declare(strict_types=1);
require __DIR__.'/core.php';require_schema();
try {
    $id=positive_id($_GET['doctor']??0);$d=doctor_actor($id,'owner',0,true);
    if(!doctor_has($id,'booking_qr',$d))throw new AuthError('امکان پوستر برای این حساب فعال نیست.',403);
    $specialty=query('SELECT name,level FROM specialties WHERE id=?',[$d['specialty_id']])->fetch();
    $data=['name'=>doctor_display_name($d['name']),'specialty'=>$specialty?specialty_display_title($specialty['name'],$specialty['level']):($d['specialty_other']??''),'photo'=>!empty($d['photo_file'])?'photo.php?id='.$id:'','logo'=>site_logo_url(),'site'=>site_name(),'domain'=>parse_url(app_base_url(),PHP_URL_HOST).rtrim((string)parse_url(app_base_url(),PHP_URL_PATH),'/'),'url'=>app_base_url().doctor_url($id,(string)$d['name'])];
} catch(Throwable $e){http_response_code($e instanceof AuthError?$e->status:422);layout_start('پوستر پزشک');echo '<p class="error">'.esc(error_message($e)).'</p>';layout_end();exit;}
